// === Tab: mySketch.js ===
// By Oliver Chang
// Github: https://github.com/oliver3109
// X: https://x.com/oliver3109
// Openprocessing: https://openprocessing.org/user/324595?o=2&view=sketches

const MAX_PARTICLE_COUNT = 90;

const colorScheme1 = ["#47CBB0"];
const colorScheme2 = ["#FFA910"];
const colorScheme3 = ["#311AE7"];

let theShader;
let shaderTexture;

const particleList = [];
let particleGroup;

function preload() {
  theShader = loadShader("https://openprocessing.org/sketch/2271629/files/vert.glsl", "frag.glsl");
}

function setup() {
  pixelDensity(1);

  createCanvas(windowWidth, max(windowWidth, windowHeight), WEBGL);
  shaderTexture = createGraphics(height, height, WEBGL);
  shaderTexture.noStroke();

  const c1 = random(colorScheme1);
  const c2 = random(colorScheme2);
  const c3 = random(colorScheme3);

  for (let i = 0; i < MAX_PARTICLE_COUNT; i++) {
    const myParticle = new Particle(width / 2, height / 2, c1);
    const myParticle1 = new Particle(width / 2, height / 2, c2);
    const myParticle2 = new Particle(width / 2, height / 2, c3);
    particleList.push(myParticle, myParticle1, myParticle2);
  }

  particleGroup = new ParticleGroup();
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  background(0);
  translate(-height / 2, -height / 2);
  shaderTexture.shader(theShader);

  const data = particleGroup.draw();

  theShader.setUniform("resolution", [height, height]);
  theShader.setUniform("particles", [...data.particles]);
  theShader.setUniform("particleCount", data.particles.length);
  theShader.setUniform("particleColors", [...data.particleColors]);

  shaderTexture.rect(0, 0, height, height);

  texture(shaderTexture);

  rect(0, 0, height, height);
}

function keyPressed() {
  if (keyCode === ENTER) {
    let fs = fullscreen();
    fullscreen(!fs);
  }
}


// === Tab: vert.glsl ===
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision mediump float;
#endif

attribute vec3 aPosition;

void main(){
  vec4 positionVec4=vec4(aPosition,1.);
  positionVec4.xy=positionVec4.xy*2.-1.;
  gl_Position=positionVec4;
}

// === Tab: frag.glsl ===
// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 resolution;

uniform int particleCount;
uniform vec3 particles[270];
uniform vec3 particleColors[270];

void main(){
  vec2 uv=gl_FragCoord.xy/resolution.xy;

  float r=0.;
  float g=0.;
  float b=0.;

  float mult=.0000009; // 强度

  for(int i=0;i<270;i++){
    if(i<particleCount){
      vec3 particle=particles[i];
      vec2 pos=particle.xy;
      float mass=particle.z;
      vec3 color=particleColors[i];

      r+=color.r/distance(uv,pos)*mult*mass;
      g+=color.g/distance(uv,pos)*mult*mass;
      b+=color.b/distance(uv,pos)*mult*mass;
    }
  }

  vec4 finalColor=vec4(r-.1,g-.1,b-.5,1.);
  gl_FragColor=finalColor;
}

// === Tab: particle.js ===
// By Oliver
// Github: https://github.com/oliver3109
// Twitter: https://twitter.com/chihyungchang66
// Openprocessing: https://openprocessing.org/user/324595?o=2&view=sketches
// Youtube: https://www.youtube.com/@creative-coder-oliver

class Particle {
  constructor(x, y, color) {
    this.pos = new p5.Vector(x, y);
    this.vel = p5.Vector.random2D();
    this.vel.mult(random(1, 20));
    this.vel.rotate(radians(random(-25, 25)));
    this.mass = random(1, 30);

		this.lifeCount = random(-100, 100);
    this.color = color;
  }

  move() {
		let attitudeX = sin(this.lifeCount / 20);
		let attitudeY = cos(this.lifeCount / 120);
		let massX = map(this.mass,0, 30, width/2, 130);
		let massY = map(this.mass,0, 30, width/2, 130);
    let x = attitudeX * (sin(this.lifeCount / 116) * massX);
    let y = attitudeY * (sin(this.lifeCount / 16) * massY);

    this.pos = new p5.Vector(width/2 + x, height /2 + y); // 居中
		// this.pos = new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + x, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + y); // 跟随鼠标
		// this.pos.add(x, y);
  }
}

function ParticleGroup() {
  this.draw = () => {
    for (let i = 0; i < particleList.length; i++) {
      const p = particleList[i];
      p.move();
			p.lifeCount++;
    }

    return this.serialize();
  };

  this.serialize = () => {
    var data = {
      particles: [],
      particleColors: [],
    };
    for (let i = 0; i < particleList.length; i++) {
      var p = particleList[i];
      let itsColor = p.color;

      data.particles.push(
        map(p.pos.x, 0, width, 0.0, 1.0),
        map(p.pos.y, 0, height, 1.0, 0.0),
        (p.mass * p.vel.mag()) / 50
      );
      data.particleColors.push(red(itsColor), green(itsColor), blue(itsColor));
    }

    return data;
  };
}

